import { useEffect, useState } from "react";

export default function AdminPage() {
  const [orders, setOrders] = useState([]);
  const [history, setHistory] = useState([]);
  const [menu, setMenu] = useState([]);
  const [activeTab, setActiveTab] = useState("status");
  const [theme, setTheme] = useState("dark");
  const [font, setFont] = useState("inter");
  const [buttonColor, setButtonColor] = useState("#2563eb");
  const [textColor, setTextColor] = useState("#ffffff");
  const [newItem, setNewItem] = useState({ category: "", name: "", price: "" });

  // Live-Updates
  useEffect(() => {
    const interval = setInterval(() => {
      const updatedOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
      setOrders(updatedOrders);
      setHistory(updatedOrders.filter(order => order.status === "Fertig"));
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    setMenu(JSON.parse(localStorage.getItem("menuData") || "[]"));
    setTheme(localStorage.getItem("theme") || "dark");
    setFont(localStorage.getItem("font") || "inter");
    setButtonColor(localStorage.getItem("buttonColor") || "#2563eb");
    setTextColor(localStorage.getItem("textColor") || "#ffffff");
  }, []);

  useEffect(() => {
    document.body.className = `${theme} font-${font}`;
    localStorage.setItem("menuData", JSON.stringify(menu));
    localStorage.setItem("theme", theme);
    localStorage.setItem("font", font);
    localStorage.setItem("buttonColor", buttonColor);
    localStorage.setItem("textColor", textColor);
  }, [menu, theme, font, buttonColor, textColor]);

  const updateOrderStatus = (index, nextStatus) => {
    const updated = [...orders];
    updated[index].status = nextStatus;
    setOrders(updated);
    localStorage.setItem("allOrders", JSON.stringify(updated));
    if (nextStatus === "Fertig") {
      localStorage.removeItem("currentOrder");
    }
  };

  const updateAvailability = (catIndex, itemIndex) => {
    const updated = [...menu];
    updated[catIndex].items[itemIndex].available = !updated[catIndex].items[itemIndex].available;
    setMenu(updated);
  };

  const deleteItem = (catIndex, itemIndex) => {
    const updated = [...menu];
    updated[catIndex].items.splice(itemIndex, 1);
    setMenu(updated);
  };

  const deleteCategory = (catIndex) => {
    const updated = [...menu];
    updated.splice(catIndex, 1);
    setMenu(updated);
  };

  const addItem = () => {
    if (!newItem.category || !newItem.name || !newItem.price) return;
    const item = {
      name: newItem.name,
      price: parseFloat(newItem.price),
      available: true,
    };
    const updated = [...menu];
    const cat = updated.find(c => c.category === newItem.category);
    if (cat) {
      cat.items.push(item);
    } else {
      updated.push({ category: newItem.category, items: [item] });
    }
    setMenu(updated);
    setNewItem({ category: "", name: "", price: "" });
  };
  return (
    <div className="min-h-screen p-6">
      <div className="flex gap-4 mb-6">
        <button onClick={() => setActiveTab("status")} className="px-4 py-2 rounded bg-blue-600 text-white">
          Bestellungen
        </button>
        <button onClick={() => setActiveTab("history")} className="px-4 py-2 rounded bg-blue-600 text-white">
          Historie
        </button>
        <button onClick={() => setActiveTab("menu")} className="px-4 py-2 rounded bg-blue-600 text-white">
          Speisekarte bearbeiten
        </button>
        <button onClick={() => setActiveTab("design")} className="px-4 py-2 rounded bg-blue-600 text-white">
          Design ändern
        </button>
      </div>

      {activeTab === "status" && (
        <div>
          <h2 className="text-2xl font-bold mb-4">Bestellungen</h2>
          {orders.filter(order => order.status !== "Fertig").length === 0 ? (
            <p>Keine offenen Bestellungen.</p>
          ) : (
            orders
              .filter(order => order.status !== "Fertig")
              .map((order, index) => (
                <div key={index} className="border p-4 mb-4 rounded bg-gray-800 text-white">
                  <p className="mb-2 font-semibold">Tisch: {order.tableNumber}</p>
                  <ul className="mb-2 list-disc pl-6">
                    {order.items.map((item, i) => (
                      <li key={i}>{item.name} – {item.price.toFixed(2)} €</li>
                    ))}
                  </ul>
                  <p className="mb-2">Status: {order.status}</p>
                  {order.status === "Ausstehend" && (
                    <button onClick={() => updateOrderStatus(index, "In Zubereitung")} className="bg-yellow-500 px-3 py-1 rounded mr-2">
                      In Zubereitung
                    </button>
                  )}
                  {order.status === "In Zubereitung" && (
                    <button onClick={() => updateOrderStatus(index, "Fertig")} className="bg-green-600 px-3 py-1 rounded">
                      Fertig
                    </button>
                  )}
                </div>
              ))
          )}
        </div>
      )}

      {activeTab === "history" && (
        <div>
          <h2 className="text-2xl font-bold mb-4">Bestellhistorie</h2>
          {history.length === 0 ? (
            <p>Keine abgeschlossenen Bestellungen.</p>
          ) : (
            history.map((order, index) => (
              <div key={index} className="border p-4 mb-4 rounded bg-gray-100 text-black">
                <p className="mb-2 font-semibold">Tisch: {order.tableNumber}</p>
                <ul className="mb-2 list-disc pl-6">
                  {order.items.map((item, i) => (
                    <li key={i}>{item.name} – {item.price.toFixed(2)} €</li>
                  ))}
                </ul>
                <p>Status: {order.status}</p>
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === "menu" && (
        <div>
          <h2 className="text-2xl font-bold mb-4">Speisekarte bearbeiten</h2>
          {menu.map((cat, catIndex) => (
            <div key={catIndex} className="mb-6">
              <div className="flex justify-between items-center mb-1">
                <h3 className="text-xl font-semibold">{cat.category}</h3>
                <button
                  onClick={() => deleteCategory(catIndex)}
                  className="text-sm text-red-500 hover:text-red-700"
                >
                  Kategorie löschen
                </button>
              </div>
              {cat.items.map((item, itemIndex) => (
                <div key={itemIndex} className="flex items-center gap-3 mb-2 bg-gray-800 p-2 rounded text-white">
                  <span className="w-48">{item.name}</span>
                  <input
                    type="number"
                    value={item.price}
                    onChange={(e) => {
                      const updated = [...menu];
                      updated[catIndex].items[itemIndex].price = parseFloat(e.target.value);
                      setMenu(updated);
                    }}
                    className="w-24 px-2 py-1 rounded text-black"
                  />
                  <label className="flex items-center ml-4">
                    <input
                      type="checkbox"
                      checked={item.available}
                      onChange={() => updateAvailability(catIndex, itemIndex)}
                      className="mr-2"
                    />
                    verfügbar
                  </label>
                  <button
                    onClick={() => deleteItem(catIndex, itemIndex)}
                    className="ml-auto bg-red-600 hover:bg-red-700 px-3 py-1 rounded text-sm"
                  >
                    Löschen
                  </button>
                </div>
              ))}
            </div>
          ))}

          <div className="mt-6">
            <h3 className="text-lg font-semibold mb-2">Neuen Artikel hinzufügen</h3>
            <div className="flex flex-col md:flex-row gap-2">
              <input
                className="p-2 rounded text-black"
                placeholder="Kategorie"
                value={newItem.category}
                onChange={(e) => setNewItem({ ...newItem, category: e.target.value })}
              />
              <input
                className="p-2 rounded text-black"
                placeholder="Name"
                value={newItem.name}
                onChange={(e) => setNewItem({ ...newItem, name: e.target.value })}
              />
              <input
                className="p-2 rounded text-black"
                placeholder="Preis"
                type="number"
                value={newItem.price}
                onChange={(e) => setNewItem({ ...newItem, price: e.target.value })}
              />
              <button onClick={addItem} className="bg-green-600 hover:bg-green-700 px-4 py-2 rounded text-white">
                Hinzufügen
              </button>
            </div>
          </div>
        </div>
      )}
      {activeTab === "design" && (
        <div>
          <h2 className="text-2xl font-bold mb-4">Design ändern</h2>

          <h3 className="text-lg font-semibold mb-2">Theme</h3>
          <div className="flex flex-wrap gap-2 mb-4">
            {[
              "dark", "light", "blue", "green", "techy",
              "edel", "minimalistisch", "classic", "elegant", "neon"
            ].map((t) => (
              <button
                key={t}
                onClick={() => setTheme(t)}
                className={`px-3 py-2 rounded ${
                  theme === t ? "bg-green-600 text-white" : "bg-gray-300 text-black"
                }`}
              >
                {t}
              </button>
            ))}
          </div>

          <h3 className="text-lg font-semibold mb-2">Button-Farbe</h3>
          <input
            type="color"
            value={buttonColor}
            onChange={(e) => setButtonColor(e.target.value)}
            className="mb-4"
          />

          <h3 className="text-lg font-semibold mb-2">Textfarbe</h3>
          <input
            type="color"
            value={textColor}
            onChange={(e) => setTextColor(e.target.value)}
            className="mb-4"
          />

          <h3 className="text-lg font-semibold mb-2">Schriftart</h3>
          <select
            value={font}
            onChange={(e) => setFont(e.target.value)}
            className="p-2 rounded text-black"
          >
            {[
              "inter", "roboto", "arial", "verdana", "tahoma", "georgia", "times",
              "courier", "comic", "montserrat", "opensans", "ubuntu", "lato",
              "notosans", "ptserif", "raleway", "sourcecode", "playfair", "merriweather",
              "baskerville"
            ].map((f) => (
              <option key={f} value={f}>{f}</option>
            ))}
          </select>
        </div>
      )}
    </div>
  );
}
